"""Metadata for constituent catalog (cocat) columns.

TODO: determine how to handle AICREFCAT_COLUMNS
TODO: determine which cocat columns should be default

Classes:
--------
ColumnInfo: container for metadata for a single column

TILE_COLUMNS: dictionary with information for columns which will hold sky tile ID + minipix index
ATLAS_COLUMNS: dictionary with information for columns of ATLAS-Refcat2
GAIA_COLUMNS: dictionary with information for columns in Gaia DR3 Source Table
PANSTARRS_COLUMNS: dictionary with information for columns in PanSTARRS ObjectThin + Mean Object Tables
AICREFCAT_COLUMNS: work in progress. 

AI Disclosure:
--------------
Cocat column dictionaries contain information pulled from respective catalog documentation pages (listed with each catalog dictionary) - 
  Claude compiled this information a CSV file for each catalog table, and these files were used to build the ColumnInfo instance for each catalog column.
The ColumnInfo and Catalog column dictionaries, and their general structure, were suggested and generated by Claude.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class ColumnInfo:
    '''Metadata container for each column of a constituent catalog.
    
    Each column in each catalog will have an entry that is an instance of this dataclass.
    These entries will go into a `<CATALOG>_COLUMNS{}` dictionary for each catalog, defined in this module,
      where each dict entry is `"column_name": ColumnInfo(args)`.
    This will go into the Catalog Metadata container class (which is now going to be separate from the catalog data container).
    '''
    aic_colname: str   # name of column in AIC Refcat
    dtype: type | str  # dtype from HATSed catalog
    unit: str | None   # unit from catalog documentation 
    is_default: bool   # column is loaded by default; these are undecided.  
    #is_tile: bool      # column holds sky tiling information (not included with catalog; this is something that we calculate) **Uncertain whether this is necessary
    description: str   # description from catalog documentation 


# Sky tiling column names (tile/tanseg ID and minipix/local index); 
# these values will be computed for each source when building AIC Refcat
TILE_COLUMNS: dict[str, ColumnInfo] = {
    "tanseg_id": ColumnInfo("tanseg_id", dtype="int32[pyarrow]", unit="dimensionless", is_default=True, description="ID of tile"),
    "local_idx": ColumnInfo("local_idx", dtype="int16[pyarrow]", unit="dimensionless", is_default=True, description="Index of minipix"),
}


# ATLAS-Refcat2 table column info from Tonry et al (2018) # https://ui.adsabs.harvard.edu/abs/2018ApJ...867..105T/abstract 
